<?php
$clients=db()->query("SELECT c.id,c.name,COUNT(a.id) visits FROM clients c LEFT JOIN attendance a ON a.client_id=c.id AND a.checkin_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) WHERE c.active=1 GROUP BY c.id ORDER BY visits")->fetchAll();
$valid=array_map(fn($c)=>(int)$c['visits'],$clients);$n=count($valid);$low=0;$mid=0;$high=0;
if($n){$centers=[min($valid),array_sum($valid)/$n,max($valid)];for($iter=0;$iter<12;$iter++){$groups=[[],[],[]];foreach($valid as $v){$ix=0;for($k=1;$k<3;$k++)if(abs($v-$centers[$k])<abs($v-$centers[$ix]))$ix=$k;$groups[$ix][]=$v;}foreach($groups as $i=>$g)if($g)$centers[$i]=array_sum($g)/count($g);}sort($centers);foreach($valid as $v){if($v<=$centers[0])$low++;elseif($v<=$centers[1])$mid++;else$high++;}}
$inactive=db()->query("SELECT c.id,c.name,MAX(a.checkin_at) last_visit FROM clients c JOIN memberships m ON m.client_id=c.id AND m.status='active' AND m.end_date>=CURDATE() LEFT JOIN attendance a ON a.client_id=c.id WHERE c.active=1 GROUP BY c.id HAVING last_visit IS NULL OR last_visit<DATE_SUB(NOW(),INTERVAL 10 DAY) ORDER BY last_visit LIMIT 8")->fetchAll();
$plans=db()->query("SELECT p.name,COUNT(m.id) uses_count FROM plans p LEFT JOIN memberships m ON m.plan_id=p.id GROUP BY p.id ORDER BY uses_count DESC LIMIT 5")->fetchAll();
$revenue=db()->query("SELECT DATE_FORMAT(payment_date,'%Y-%m') label,SUM(amount) total FROM payments WHERE status='completed' AND payment_date>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY DATE_FORMAT(payment_date,'%Y-%m') ORDER BY label")->fetchAll();
$trend='Aún hay pocos datos para estimar la tendencia.';$forecast=null;if(count($revenue)>=3){$ys=array_map(fn($r)=>(float)$r['total'],$revenue);$xs=range(0,count($ys)-1);$xm=array_sum($xs)/count($xs);$ym=array_sum($ys)/count($ys);$num=0;$den=0;foreach($xs as $i=>$x){$num+=($x-$xm)*($ys[$i]-$ym);$den+=($x-$xm)**2;}$slope=$den?$num/$den:0;$forecast=max(0,$ys[count($ys)-1]+$slope);$trend=$slope>=0?'Los ingresos muestran una tendencia creciente.':'Los ingresos muestran una tendencia decreciente.';}
?>
<div class="alert">Análisis local sin servicios externos: segmentación de frecuencia con <b>k-means (1 variable)</b>, tendencia por regresión lineal y reglas de seguimiento. Es una ayuda exploratoria, no una predicción garantizada.</div><div class="grid stats"><article class="card stat"><div class="stat-top">Alta frecuencia · 30 días</div><div class="stat-value"><?=$high?></div><div class="stat-foot">Segmento con más visitas</div></article><article class="card stat"><div class="stat-top">Frecuencia media</div><div class="stat-value"><?=$mid?></div><div class="stat-foot">Segmento intermedio</div></article><article class="card stat"><div class="stat-top">Frecuencia baja</div><div class="stat-value"><?=$low?></div><div class="stat-foot">Revisar estrategia de retención</div></article><article class="card stat"><div class="stat-top">Estimación próximo mes</div><div class="stat-value" style="font-size:22px"><?=$forecast===null?'—':money($forecast)?></div><div class="stat-foot">Regresión lineal sobre hasta 6 meses</div></article></div>
<div class="grid cols"><section class="card panel"><div class="panel-head"><h2>Seguimiento recomendado</h2><small>Sin visita en 10 días · membresía vigente</small></div><div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>ÚLTIMA VISITA</th><th>ACCIÓN SUGERIDA</th></tr></thead><tbody><?php foreach($inactive as $r): ?><tr><td><?=h($r['name'])?></td><td><?=$r['last_visit']?date('d/m/Y',strtotime($r['last_visit'])):'Sin registros'?></td><td>Contactar y consultar cómo apoyar su rutina</td></tr><?php endforeach; ?><?php if(!$inactive): ?><tr><td colspan="3" class="empty">No hay clientes que cumplan esta regla actualmente.</td></tr><?php endif; ?></tbody></table></div></section><section class="card panel"><div class="panel-head"><h2>Planes más utilizados</h2></div><table><thead><tr><th>PLAN</th><th>MEMBRESÍAS</th></tr></thead><tbody><?php foreach($plans as $p): ?><tr><td><?=h($p['name'])?></td><td><?=$p['uses_count']?></td></tr><?php endforeach; ?></tbody></table><p class="muted" style="font-size:11px;margin-top:18px"><?=h($trend)?></p></section></div><section class="card panel"><div class="panel-head"><h2>Frecuencia de asistencia por cliente</h2><small>Últimos 30 días · <?=count($clients)?> perfiles</small></div><div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>VISITAS</th><th>SEGMENTO K-MEANS</th></tr></thead><tbody><?php foreach($clients as $c): $v=(int)$c['visits'];$seg=$v<=$centers[0]?'Baja':($v<=$centers[1]?'Media':'Alta'); ?><tr><td><?=h($c['name'])?></td><td><?=$v?></td><td><span class="pill <?=$seg==='Baja'?'warning':''?>"><?=h($seg)?></span></td></tr><?php endforeach; ?><?php if(!$clients): ?><tr><td colspan="3" class="empty">Agrega clientes y asistencias para formar segmentos.</td></tr><?php endif; ?></tbody></table></div></section>
